mapper.insert:
insert into t_role (name, status, remark) value
    (#{name},#{status},#{remark});
set @lastId=LAST_INSERT_ID();

    insert into t_role_menu (rid,mid) values

        (@lastId, #{item})

mapper.update:
update t_role set name=#{name},status=#{status},remark=#{remark},sort=#{sort} where id=#{id};

    delete from t_role_menu where rid=#{id};
    insert into t_role_menu (rid,mid) values

            (#{id}, #{item})

mapper.delete:
delete from t_role where id in (

    #{item}
);
delete from t_role_menu where rid in (

        #{item}

);

mapper.select:
select a.*, rm.mid mid,rm.rid aid from t_role a
    left join t_role_menu rm on a.id = rm.rid
where a.id=#{id}
